class SlidingWindowRateLimiter:
    """In-memory per-path/IP guard to avoid accidental API abuse."""
    def __init__(self) -> None:
        self._buckets: Dict[str, Deque[float]] = defaultdict(deque)

    def allow(self, key: str, limit_per_minute: int) -> bool:
        if limit_per_minute <= 0:
            return True

        now = time.time()
        window_start = now - 60.0

        dq = self._buckets[key]
        while dq and dq[0] < window_start:
            dq.popleft()

        if len(dq) >= limit_per_minute:
            return False

        dq.append(now)
        return True

    def gc(self, ttl_seconds: int) -> None:
        if ttl_seconds <= 0:
            return
        if len(self._buckets) < 10000:
            return
        cutoff = time.time() - float(ttl_seconds)
        for k, dq in list(self._buckets.items()):
            if not dq or dq[-1] < cutoff:
                self._buckets.pop(k, None)


rate_limiter = SlidingWindowRateLimiter()


def _client_ip(request: Request) -> str:
    """Resolve client IP, optionally honoring proxy headers when enabled."""
    if TRUST_PROXY:
