def _precision_and_coverage(
    y_true: np.ndarray,
    probs: np.ndarray,
    threshold: float,
):
    mask = probs >= threshold
    if mask.sum() == 0:
        return None, 0.0, 0
    precision = float((y_true[mask] == 1).mean())
    coverage = float(mask.mean())
    return precision, coverage, int(mask.sum())

