def _normalize_branch(branch: Optional[str]) -> Optional[str]:
    if not branch:
        return None
    b = branch.strip()

    # UI sometimes sends "(Main)" / "(master)" / "(0)" / "Master"
    if b.startswith("(") and b.endswith(")"):
        b = b[1:-1].strip()

    if not b or b.isdigit():
        return None

    low = b.lower()
    if low in {"main", "master"}:
        return low

    if not _SAFE_BRANCH.match(b):
        return None

    return b

