        "low_confidence_route_rate_max": _float_env("AEGIS_CONTRACT_MAX_LOW_CONFIDENCE_ROUTE_RATE", 0.75),
    }

    breaches: List[str] = []
    if safety_rate > thresholds["safety_fallback_rate_max"]:
