def _serialize_root(entry: Path) -> Dict[str, Any]:
    stat = entry.stat()
    rel = entry.relative_to(PROJECT_ROOT)
    info: Dict[str, Any] = {
        "name": entry.name,
        "path": str(rel),
        "type": "dir" if entry.is_dir() else "file",
        "is_dir": entry.is_dir(),
        "size": stat.st_size,
        "modified": int(stat.st_mtime * 1000),
    }
    if entry.is_dir():
        try:
            children = list(entry.iterdir())
            info["items"] = len(children)
        except Exception:
            info["items"] = None
    return info

