def _predict_proba_series(model, X) -> List[float]:
    if model is None:
        return [0.0] * len(X)
    try:
        probs = model.predict_proba(X)
        return [float(row[1]) for row in probs]
    except Exception as exc:  # noqa: BLE001
        logger.warning("predict_proba failed for %s: %s", type(model), exc)
        return [0.0] * len(X)

