def _parse_scope_env(name: str, default: str = "") -> list[str]:
    raw = (os.getenv(name, default) or default).strip()
    if not raw:
        return []
    scopes: list[str] = []
    seen: set[str] = set()
    for token in raw.replace(",", " ").split():
        value = token.strip().lower()
        if not value or value in seen:
            continue
        seen.add(value)
        scopes.append(value)
    return scopes

