def _python_module_for_rel_path(rel_path: str) -> str:
    rel = str(rel_path or "").replace("\\", "/").strip("/")
    if not rel.endswith(".py"):
        return ""
    parts = list(Path(rel).with_suffix("").parts)
    if parts and parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)

