def _python_package_parts_for_rel_path(rel_path: str) -> List[str]:
    module = _python_module_for_rel_path(rel_path)
    if not module:
        return []
    parts = module.split(".")
    path_parts = list(Path(str(rel_path or "")).parts)
    if path_parts and path_parts[-1] == "__init__.py":
        return parts
    return parts[:-1]

