def scan_python_call_counts(path: Path) -> Counter[str]:
    if path.suffix.lower() != ".py":
        return Counter()
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return Counter()
    if not text.strip():
        return Counter()
