                items.extend(fetched)
        except Exception:
            pass

    if len(items) < limit:
        try:
            fetched = _fetch_gdelt(sym, min(limit - len(items), NEWS_MAX))
            if fetched:
                providers.append("gdelt")
                items.extend(fetched)
        except Exception:
