        "symbol": sym,
        "items": items,
        "momentum": round(momentum, 3),
        "trust_avg": round(trust_avg, 3),
        "fetched_at": int(now),
        "provider": ",".join(providers) if providers else "gdelt",
    }
    _cache[sym] = (now, payload)
    return payload

