def _resolve_lang(lang: Optional[str]) -> str:
    if not lang:
        return DDG_LANG
    raw = lang.strip().lower().replace("_", "-")
    if raw in {"es", "es-es", "es-mx", "es-419", "spanish"}:
        return "es-es"
    if raw in {"en", "en-us", "en-gb", "english"}:
        return "en-us"
    if "-" not in raw and len(raw) == 2:
        return f"{raw}-{raw}"
    return raw

