def _decode_qwant_href(href: str) -> str:
    try:
        parsed = urlparse(href)
        if "qwant.com" in parsed.netloc and "/redirect" in parsed.path:
            target = parse_qs(parsed.query).get("u")
            if target:
                return unquote(target[0])
    except Exception:
        return href
    return href

